      "catalogVersionUndated": "\u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u043C\u0430\u044F \u0432\u0435\u0440\u0441\u0438\u044F \u043D\u0430 \u043C\u043E\u043C\u0435\u043D\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430 \u2014 \u043A\u0430\u0442\u0430\u043B\u043E\u0433 \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0435\u0436\u0435\u0434\u043D\u0435\u0432\u043D\u043E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u043E\u0432\u044B\u0435 \u0432\u044B\u043F\u0443\u0441\u043A\u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u043E\u0432 \u043C\u043E\u0433\u0443\u0442 \u0435\u0449\u0451 \u043D\u0435 \u043F\u043E\u044F\u0432\u0438\u0442\u044C\u0441\u044F",
      "catsLess": "\u041C\u0435\u043D\u044C\u0448\u0435 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439",
      "catsMore": "\u0411\u043E\u043B\u044C\u0448\u0435 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439",
      "checkBundles": "\u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u0432 (\u043F\u0430\u043A\u0435\u0442\u044B)",
      "checkBundlesEmpty": "\u041D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u044B \u043D\u0438 \u043E\u0434\u0438\u043D \u043F\u0430\u043A\u0435\u0442 \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u0432",
      "checkCommunity": "\u0421\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E",
      "checkConfigNamespaceNone": "\u043E\u043D\u043E \u043D\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u0441\u0432\u043E\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0437\u0430\u043F\u0438\u0441\u0438",
      "checkConfigNamespaceOwn": "\u0441\u0432\u043E\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0437\u0430\u043F\u0438\u0441\u0438",
      "checkConfigNamespaceRow": "\u043E\u043D\u043E \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0432\u043E\u044E \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044E \u0438\u0437 \xAB{0}\xBB, \u0447\u0442\u043E \u043D\u0435 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u043E\u043C \u0437\u0430\u043F\u0438\u0441\u0438",
      "checkConfigNamespaces": "\u041F\u043B\u0430\u0433\u0438\u043D\u044B, \u0443 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0447\u0438\u0442\u0430\u044E\u0442 \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0438\u043C\u044F",
      "checkConfigNamespacesEmpty": "\u041D\u0438 \u043E\u0434\u0438\u043D \u043F\u043B\u0430\u0433\u0438\u043D \u044D\u0442\u043E\u0433\u043E \u043D\u0435 \u0434\u0435\u043B\u0430\u0435\u0442.",
      "checkConfigNamespacesHint": "\u041F\u0430\u043D\u0435\u043B\u044C \u043F\u043B\u0430\u0433\u0438\u043D\u0430 \u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u0443\u044E \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044E \u043F\u043E ENTRY ID. \u0415\u0441\u043B\u0438 \u0438\u043C\u044F \u0443\u043A\u0430\u0437\u0430\u043D\u043E \u043D\u0435\u0432\u0435\u0440\u043D\u043E, \u043E\u0448\u0438\u0431\u043A\u0430 \u043D\u0435 \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u0435\u0442: \u043F\u0430\u043D\u0435\u043B\u044C \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043F\u0443\u0441\u0442\u043E\u0439 \u0438 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C\u0441\u044F, \u0430 \u043F\u043B\u0430\u0433\u0438\u043D \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0442\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043E\u043D \u043F\u0440\u043E\u043F\u0438\u0441\u0430\u043B \u0436\u0451\u0441\u0442\u043A\u043E (\u0434\u043B\u044F \u043F\u0430\u043D\u0435\u043B\u0435\u0439-\u0445\u043E\u043B\u0441\u0442\u043E\u0432 \u044D\u0442\u043E \u0431\u0435\u043B\u044B\u0439 \u044D\u043A\u0440\u0430\u043D). \u041E\u0448\u0438\u0431\u043A\u0430 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432\u043D\u0443\u0442\u0440\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u0441\u043A\u043E\u0433\u043E \u043F\u0430\u043A\u0435\u0442\u0430 \u0441\u0430\u043C\u043E\u0433\u043E \u043F\u043B\u0430\u0433\u0438\u043D\u0430 \u2014 \u0440\u044B\u043D\u043E\u043A \u0438\u0441\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0435\u0451 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442, \u043D\u0443\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043E\u0434\u043D\u0443 \u0441\u0442\u0440\u043E\u043A\u0443 \u043A\u043E\u0434\u0430 \u0443 \u0430\u0432\u0442\u043E\u0440\u0430.",
      "checkDir": "\u0434\u0438\u0440\u0435\u043A\u0442\u043E\u0440\u0438\u044F",
      "checkDuplicates": "\u0414\u0443\u0431\u043B\u0438\u0440\u0443\u044E\u0449\u0438\u0435\u0441\u044F \u0437\u0430\u043F\u0438\u0441\u0438 \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u0432",
