      "checkOverridden": "\u041F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u043E",
      "checkOverrides": "\u041F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u044F",
      "checkOverridesEmpty": "\u041D\u0435\u0442 \u043F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0439",
      "checkPatch": "\u0444\u0430\u0439\u043B \u043F\u0430\u0442\u0447\u0430",
