      "published": "\u0414\u0430\u0442\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
      "queuedBadge": "\u0412 \u043E\u0447\u0435\u0440\u0435\u0434\u0438",
      "queuedInstallGone": "\u041F\u043B\u0430\u0433\u0438\u043D, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0434\u043E\u043B\u0436\u043D\u0430 \u0431\u044B\u043B\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u044D\u0442\u0430 \u0437\u0430\u043F\u0438\u0441\u044C, \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0432 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0435 (\u043A\u0430\u0442\u0430\u043B\u043E\u0433 \u0431\u044B\u043B \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D \u0438\u043B\u0438 \u0432\u044B \u0441\u043C\u0435\u043D\u0438\u043B\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443), \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0437\u0430\u043F\u0438\u0441\u044C \u0443\u0434\u0430\u043B\u0435\u043D\u0430. \u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0435 \u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E.",
      "queuedRunBlocked": "\u0420\u0430\u0431\u043E\u0442\u0430\u044E\u0449\u0438\u0445 \u0441\u0435\u0441\u0441\u0438\u0439: {0} \u2014 \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u044D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435\u043B\u044C\u0437\u044F \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C: \u044D\u0442\u0438 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u0438 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0444\u0430\u0439\u043B\u044B \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u0432 \u043D\u0430 \u043C\u0435\u0441\u0442\u0435, \u0438 \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0449\u0438\u0439 \u0430\u0433\u0435\u043D\u0442 \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0435\u0440\u0432\u0430\u0442\u044C\u0441\u044F \u043F\u043E\u0441\u0440\u0435\u0434\u0438 \u0445\u043E\u0434\u0430. \u041A\u0430\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u043D\u0438 \u0441\u0442\u0430\u043D\u0443\u0442 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u043C\u0438, \u0432\u0441\u0451 \u043D\u0430\u0447\u043D\u0451\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 (\u0438\u043B\u0438 \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u0435 \u044D\u0442\u0443 \u0437\u0430\u043F\u0438\u0441\u044C \u0432 \xAB\u0417\u0430\u0434\u0430\u0447\u0430\u0445\xBB).",
      "queuedRunBusy": "\u0414\u0440\u0443\u0433\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430, \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u0432\u0441\u0451 \u0435\u0449\u0451 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u044D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435\u043B\u044C\u0437\u044F \u043D\u0430\u0447\u0430\u0442\u044C: \u043E\u043D\u0430 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u0432 \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0438 \u043D\u0430\u0447\u043D\u0451\u0442\u0441\u044F \u0441\u0430\u043C\u0430 \u043F\u043E \u0441\u0435\u0431\u0435 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u2014 \u043D\u0435\u0442 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u043D\u0430\u0436\u0438\u043C\u0430\u0442\u044C \u0441\u043D\u043E\u0432\u0430.",
