      "btn.save": "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C",
      "btn.test": "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C",
      "btn.testConnection": "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435",
      "card.desc": "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430\u043C\u0438 MCP: \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u044B stdio \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u044B\u0435 \u0441\u0435\u0440\u0432\u0438\u0441\u044B streamable-http; \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0433\u043E\u0440\u044F\u0447\u043E \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u0438\u0445 \u043A\u0430\u043A \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B mcp__<server>__<tool> \u2014 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F.",
      "card.name": "\u041A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044F MCP-\u0441\u0435\u0440\u0432\u0435\u0440\u043E\u0432",
      "error.argsNotArray": "\u0430\u0440\u0433\u0443\u043C\u0435\u043D\u0442\u044B \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C JSON-\u043C\u0430\u0441\u0441\u0438\u0432\u043E\u043C \u0441\u0442\u0440\u043E\u043A",
      "error.duplicateName": "\u0438\u043C\u044F \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0443\u0436\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442: {name}",
      "error.externalClash": "\u0418\u043C\u044F \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \xAB{name}\xBB \u0443\u0436\u0435 \u0437\u0430\u043D\u044F\u0442\u043E \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u043E\u043C mcp-client \u0432\u043D\u0435 \u044D\u0442\u043E\u0433\u043E \u043F\u043B\u0430\u0433\u0438\u043D\u0430 ({id}): \u0434\u0432\u0430 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u0430 \u0431\u0443\u0434\u0443\u0442 \u043A\u043E\u043D\u0444\u043B\u0438\u043A\u0442\u043E\u0432\u0430\u0442\u044C \u043F\u043E \u0438\u043C\u0435\u043D\u0430\u043C \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u043E\u0432, \u0438 \u043E\u0434\u0438\u043D \u0438\u0437 \u043D\u0438\u0445 \u043D\u0435\u0438\u0437\u0431\u0435\u0436\u043D\u043E \u043F\u0440\u043E\u0432\u0430\u043B\u0438\u0442 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0443. \u0421\u0442\u0440\u043E\u043A\u0430 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0434\u0440\u0443\u0433\u0438\u043C \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u043C \u2014 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u0435 \u0435\u0451 \u0432 \u0435\u0433\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445.",
      "error.unknown": "\u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430\u044F \u043E\u0448\u0438\u0431\u043A\u0430",
      "error.unparsableLine": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0440\u0430\u0437\u043E\u0431\u0440\u0430\u0442\u044C \u0441\u0442\u0440\u043E\u043A\u0443: {line}",
      "list.agentBudget": "\u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B MCP \u0441\u0443\u043C\u043C\u0430\u0440\u043D\u043E \u0434\u0430\u044E\u0442 {total} \u2014 \u044D\u0442\u043E \u0431\u043E\u043B\u044C\u0448\u0435 \u043B\u0438\u043C\u0438\u0442\u0430 {budget}: \u043E\u043D\u0438 \u0435\u0434\u0443\u0442 \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u0437\u0430\u043F\u0440\u043E\u0441\u0435. \u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u043B\u0438\u0448\u043D\u0438\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u2014 \u043E\u0442\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u0430\u044F \u0441\u0442\u0440\u043E\u043A\u0430 \u043D\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B \u0438 \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u0451\u0442 \u0447\u0442\u043E-\u043B\u0438\u0431\u043E \u0441\u0442\u043E\u0438\u0442\u044C.",
      "list.conflict": "\u043A\u043E\u043D\u0444\u043B\u0438\u043A\u0442 \u0438\u043C\u0435\u043D\u0438 \u0441\u0435\u0440\u0432\u0435\u0440\u0430",
